pragma solidity ^0.8.20;
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract CertificateNFT is ERC721URIStorage, Ownable {
    uint256 private _tokenIdCounter;
    event CertificateMinted(address indexed student, uint256 tokenId, string uri);

    constructor() ERC721("Web3Connect Certificate", "W3CERT") Ownable(msg.sender) {}

    function mintCertificate(address student, string memory uri)
        public onlyOwner returns (uint256)
    {
        _tokenIdCounter++;
        uint256 id = _tokenIdCounter;
        _safeMint(student, id);
        _setTokenURI(id, uri);
        emit CertificateMinted(student, id, uri);
        return id;
    }
    function transferFrom(...) override pure { revert("Soulbound"); }
}

async function mintCertificate(studentAddress, tokenURI) {
  const provider = new ethers.JsonRpcProvider(process.env.POLYGON_RPC_URL);
  const wallet = new ethers.Wallet(process.env.WALLET_PRIVATE_KEY, provider);
  const contract = new ethers.Contract(CONTRACT_ADDRESS, ABI, wallet);

  const tx = await contract.mintCertificate(studentAddress, tokenURI);
  const receipt = await tx.wait();

  return {
    txHash: receipt.hash,
    tokenId: receipt.logs[0].topics[3],
  };
}

async function uploadToIPFS(filePath) {
  const FormData = require("form-data");
  const fs = require("fs");
  const form = new FormData();
  form.append("file", fs.createReadStream(filePath));

  const res = await axios.post(
    "https://api.pinata.cloud/pinning/pinFileToIPFS",
    form,
    { headers: {
        ...form.getHeaders(),
        pinata_api_key: process.env.PINATA_API_KEY,
        pinata_secret_api_key: process.env.PINATA_SECRET_KEY,
      },
      maxBodyLength: Infinity,
    }
  );
  return `https://gateway.pinata.cloud/ipfs/${res.data.IpfsHash}`;
}

function authMiddleware(req, res, next) {
  const header = req.headers.authorization;
  if (!header?.startsWith("Bearer "))
    return res.status(401).json({ error: "No token" });

  try {
    req.user = jwt.verify(header.split(" ")[1], process.env.JWT_SECRET);
    next();
  } catch {
    res.status(401).json({ error: "Invalid token" });
  }
}

